package com.hbm.machine.oilextraction;
import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import snownee.jade.api.*;import snownee.jade.api.config.IPluginConfig;
/** Source three pump status icons are exposed as localized Jade status with real resource bars. */
@WailaPlugin public final class OilDrillJadePlugin implements IWailaPlugin {
 @Override public void register(IWailaCommonRegistration event){event.registerBlockDataProvider(Provider.INSTANCE,OilDrillEntity.class);event.registerBlockDataProvider(Provider.INSTANCE,OilDrillPort.class);}@Override public void registerClient(IWailaClientRegistration event){event.registerBlockComponent(Provider.INSTANCE,OilDrillBlock.class);}
 private enum Provider implements IServerDataProvider<BlockAccessor>,IBlockComponentProvider{INSTANCE;@Override public ResourceLocation getUid(){return ResourceLocation.parse("hbm:oil_drill");}@Override public void appendServerData(CompoundTag tag,BlockAccessor a){var m=a.getBlockEntity() instanceof OilDrillEntity drill?drill:a.getBlockEntity() instanceof OilDrillPort port?port.core():null;if(m!=null){tag.putInt("oilIndicator",m.indicator);tag.putInt("oilConsumption",m.powerRequired());tag.putInt("oilDelay",m.delay());}}@Override public void appendTooltip(ITooltip tooltip,BlockAccessor a,IPluginConfig config){var tag=a.getServerData();if(!tag.contains("oilIndicator"))return;tooltip.add(Component.translatable("gui.hbm.oil_drill.state."+tag.getInt("oilIndicator")));tooltip.add(Component.translatable("gui.hbm.oil_drill.consumption",tag.getInt("oilConsumption")));}}
}
